URLS = {
'naics-structure.csv':'https://www.statcan.gc.ca/en/statistical-programs/document/naics-scian-2022-structure-v1-eng.csv',
'naics-elements.csv':'https://www.statcan.gc.ca/en/statistical-programs/document/naics-scian-2022-element-v1-eng.csv',
'noc-structure.csv':'https://www.statcan.gc.ca/en/subjects/standard/noc/2021/indexV1/noc-2021-v1.0-classification-structure.csv',
'noc-elements.csv':'https://www.statcan.gc.ca/en/subjects/standard/noc/2021/indexV1/noc-2021-v1.0-elements.csv'}

def write_json(name, data):
    path=HERE/name
    path.write_text(json.dumps(data,indent=2,ensure_ascii=False)+'\n')
    return hashlib.sha256(path.read_bytes()).hexdigest()

def build():
    cache=CACHE; cache.mkdir(parents=True,exist_ok=True)
    manifest=[]; data={}
    for fn,url in URLS.items():
        if not (cache/fn).exists():
            import urllib.request
            (cache/fn).write_bytes(urllib.request.urlopen(url,timeout=60).read())
        raw=(cache/fn).read_bytes()
        data[fn]=list(csv.DictReader(raw.decode('utf-8-sig').splitlines(keepends=True)))
        manifest.append({'filename':fn,'url':url,'sha256':hashlib.sha256(raw).hexdigest(),'bytes':len(raw),'rows':len(data[fn]),'downloaded_on':'2026-10-06','licence':'Statistics Canada Open Licence','licence_url':'https://www.statcan.gc.ca/en/terms-conditions/open-licence'})
    write_json('sources.json',manifest)
    facts=[]; codebook={}; controls=[]; split={}
    for kind,families in FAMILIES.items():
        names=[f[0] for f in families]; random.Random(61006).shuffle(names)
        dev=set(names[:4]); split[kind]={'dev_families':sorted(dev),'test_families':sorted(set(names)-dev)}
        for fi,(name,a,b,af,bf,missing) in enumerate(families):
            structures=data[f'{kind}-structure.csv']; elements=data[f'{kind}-elements.csv']
            ckey='Code' if kind=='naics' else 'Code - NOC 2021 V1.0'
            tkey='Element Type Label' if kind=='naics' else 'Element Type Label English'
            xkey='Element Description' if kind=='naics' else 'Element Description English'
            for code in [a,b]:
                row_idx,row=next((i,r) for i,r in enumerate(structures,2) if r[ckey]==code)
                codebook[f'{kind}:{code}']={'scheme':kind,'code':code,'title':row['Class title'],'definition':row['Class definition'],'structure_source':{'file':f'{kind}-structure.csv','csv_record':row_idx},'elements':[{'type':r[tkey],'text':r[xkey].strip(),'source':{'file':f'{kind}-elements.csv','csv_record':i}} for i,r in enumerate(elements,2) if r[ckey]==code and r[tkey] in ['Main duties','Exclusion(s)','Inclusion(s)']]}
                erow=next((i,r) for i,r in enumerate(elements,2) if r[ckey]==code and r[tkey]=='All examples')
                controls.append({'id':f'{kind}-{name}-{code}-control','scheme':kind,'text':erow[1][xkey].strip(),'code':code,'origin':'official_verbatim','source':{'file':f'{kind}-elements.csv','csv_record':erow[0]}})
            # A and B cases plus a repeated fact bundle in independent wording.
            third=a if fi%2==0 else b
            for j in range(4):
                target=[a,b,third,None][j]
                reference={'decision':'code' if target else 'review','code':target,'compatible_codes':[target] if target else [a,b],'missing_discriminator':None if target else missing}
                facts.append({'id':f'{kind}-{name}-{j+1:02d}','scheme':kind,'classification_version':'NAICS Canada 2022 V1.0' if kind=='naics' else 'NOC 2021 V1.0','family':name,'split':'dev' if name in dev else 'test','variant':['complete_a','complete_b','complete_reworded','insufficient'][j],'facts':(af if target==a else bf) if target else ['the record is explicitly unresolved between the two stated alternatives',missing+' is not established'],'reference':reference,'boundary_codes':[a,b],'source_keys':[f'{kind}:{a}',f'{kind}:{b}'],'construction':'Synthetic facts and labels authored by a research agent before narrative materialization; no evaluated model used.'})
    write_json('source-evidence.json',codebook)
    write_json('split.json',split)
    facts_hash=write_json('facts-gold.json',facts)
    # Only after the separate reference ledger exists do we materialize narratives.
    cases=[]
    for kind,families in FAMILIES.items():
        for fi,family in enumerate(families):
            for j,text in enumerate(NARRATIVES[kind][fi]):
                record=next(r for r in facts if r['id']==f'{kind}-{family[0]}-{j+1:02d}')
                cases.append({k:record[k] for k in ['id','scheme','classification_version','family','split','variant']} | {'origin':'synthetic_agent_authored','text':text})
    assert len(cases)==96 and len({c['id'] for c in cases})==96
    write_json('cases.json',cases);write_json('official-controls.json',controls)
    write_json('construction.json',{'facts_written_before_narrative_file':True,'facts_sha256_at_narrative_creation':facts_hash,'reference_origin':'Official classifications plus explicitly disclosed research-agent synthesis; independent of evaluated GPT-6 Luna.','narrative_origin':'Research-agent authored, not observed survey or business-register text.','near_duplicate_note':'Cases 1/2 and case 3 share fact bundles within a family. Family-level splits keep these together; case-level errors are not independent.','review_scope':'Review cases explicitly name an unresolved distinction. Compatible code sets refer to those stated alternatives, not generic vague occupational text.','freeze_stage':'constructed, awaiting independent label audit','seed':61006})
    print(json.dumps({'cases':len(cases),'controls':len(controls),'facts_sha256':facts_hash,'split':split},indent=2))

if __name__=='__main__':build()
